async fn checked<T>(grant:&dyn CurrentQuoteGrant,future:impl Future<Output=T>)->Result<T>{grant.require_current().await?;let result=future.await;grant.require_current().await?;Ok(result)}
fn hash(raw:&str)->String{hex::encode(Sha256::digest(raw.as_bytes()))}
fn enabled()->bool{std::env::var("VAAK_REDIS_ENABLED").map(|v|!matches!(crate::library::card::php_trim(&v).to_ascii_lowercase().as_str(),"0"|"false"|"off"|"no")).unwrap_or(true)}
fn int(value:&Value)->i64{value.as_i64().unwrap_or_else(||if let Some(n)=value.as_f64(){n as i64}else if let Some(s)=value.as_str(){crate::profile_quote_warm::php_int(s)}else{i64::from(value.as_bool()==Some(true)||value.as_array().is_some_and(|v|!v.is_empty())||value.as_object().is_some_and(|v|!v.is_empty()))})}
