 pub(crate) fn configured(cfg:crate::config::Config)->Self{let mut php=std::env::var_os("VAAK_PHP_BIN").map(PathBuf::from).unwrap_or_else(crate::profile_quote_warm::php_cli_binary);if php.as_os_str().is_empty()||php.to_string_lossy().contains("php-fpm"){php=crate::profile_quote_warm::php_cli_binary()}Self{cfg,api_root:std::env::var_os("VAAK_API_ROOT").map(PathBuf::from).unwrap_or_else(||"/srv/mkultra/html/api".into()),php,temp_root:std::env::temp_dir(),#[cfg(test)]http_fixture:None}}
 async fn connection(&self,queue:bool,grant:&dyn CurrentQuoteGrant)->Result<Option<redis::aio::MultiplexedConnection>>{if !enabled(){return Ok(None)}let url=if queue{&self.cfg.redis_queue_url}else{&self.cfg.redis_url};Ok(checked(grant,tokio::time::timeout(Duration::from_millis(80),crate::redis_util::connect(url))).await?.ok().and_then(Result::ok))}
 pub(crate) async fn circuit_allow(&self,provider:&str,now:i64,grant:&dyn CurrentQuoteGrant)->Result<bool>{let Some(mut cache)=self.connection(false,grant).await?else{return Ok(true)};let key=format!("vaak:circuit:v1:{}",hash(&provider.to_ascii_lowercase()));let state=checked(grant,tokio::time::timeout(Duration::from_millis(80),crate::redis_util::json_get(&mut cache,&key))).await?.ok().and_then(Result::ok).flatten();let Some(state)=state.filter(|v|v.is_array()||v.is_object())else{return Ok(true)};let until=int(&state["open_until"]);if until>now{return Ok(false)}if until>0{let Some(mut queue)=self.connection(true,grant).await?else{return Ok(false)};let locked=checked(grant,tokio::time::timeout(Duration::from_millis(80),crate::redis_util::lock(&mut queue,&format!("circuit-probe:{provider}"),15,&std::process::id().to_string()))).await?;if let Ok(Ok(acquired))=locked{self.metric(if acquired{"lock_acquired"}else{"lock_contended"},grant).await?;return Ok(acquired)}return Ok(false)}Ok(true)}
 async fn metric(&self,name:&str,grant:&dyn CurrentQuoteGrant)->Result<()>{let Some(mut cache)=self.connection(false,grant).await?else{return Ok(())};let key=format!("vaak:metric:{name}");let count=checked(grant,tokio::time::timeout(Duration::from_millis(80),redis::cmd("INCRBY").arg(&key).arg(1).query_async::<i64>(&mut cache))).await?;if matches!(count,Ok(Ok(_))){let _=checked(grant,tokio::time::timeout(Duration::from_millis(80),redis::cmd("EXPIRE").arg(&key).arg(604800).query_async::<i64>(&mut cache))).await?;}Ok(())}
 pub(crate) async fn circuit_result(&self,provider:&str,failed:bool,now:i64,grant:&dyn CurrentQuoteGrant)->Result<()>{let Some(mut cache)=self.connection(false,grant).await?else{return Ok(())};let key=format!("vaak:circuit:v1:{}",hash(&provider.to_ascii_lowercase()));if !failed{let _=checked(grant,tokio::time::timeout(Duration::from_millis(80),redis::cmd("DEL").arg(&key).query_async::<i64>(&mut cache))).await?;return Ok(())}let state=checked(grant,tokio::time::timeout(Duration::from_millis(80),crate::redis_util::json_get(&mut cache,&key))).await?.ok().and_then(Result::ok).flatten();let failures=state.as_ref().filter(|v|v.is_object()||v.is_array()).map(|v|int(&v["failures"])).unwrap_or(0).saturating_add(1);let until=if failures>=3{now+900.min(60*(1i64<<((failures-3).clamp(0,4) as u32)))}else{0};let state=json!({"failures":failures,"open_until":until,"updated_at":now});let _=checked(grant,tokio::time::timeout(Duration::from_millis(80),crate::redis_util::json_set(&mut cache,&key,&state,1800))).await?;Ok(())}
 async fn timing(&self,ms:f64,grant:&dyn CurrentQuoteGrant)->Result<()>{self.timing_named("link_preview.http",ms,grant).await}
 pub(crate) async fn timing_named(&self,name:&str,ms:f64,grant:&dyn CurrentQuoteGrant)->Result<()>{
  if ms<0.0{return Ok(())}let Some(mut cache)=self.connection(false,grant).await?else{return Ok(())};let key=format!("vaak:timing:v1:{name}");let key=key.as_str();let mut count=redis::cmd("HINCRBY");count.arg(key).arg("count").arg(1);let mut total=redis::cmd("HINCRBYFLOAT");total.arg(key).arg("total_ms").arg(ms.to_string());for command in [count,total]{if !matches!(checked(grant,tokio::time::timeout(Duration::from_millis(80),command.query_async::<redis::Value>(&mut cache))).await?,Ok(Ok(_))){return Ok(())}}
  let max=checked(grant,tokio::time::timeout(Duration::from_millis(80),redis::cmd("HGET").arg(key).arg("max_ms").query_async::<Option<String>>(&mut cache))).await?;let max=match max{Ok(Ok(max))=>max.and_then(|v|v.parse::<f64>().ok()).unwrap_or(0.0),_=>return Ok(())};let formatted=format!("{ms:.3}");let mut commands=Vec::new();if ms>max{let mut command=redis::cmd("HSET");command.arg(key).arg("max_ms").arg(&formatted);commands.push(command)}let mut expire=redis::cmd("EXPIRE");expire.arg(key).arg(86400);commands.push(expire);let sample=format!("{key}:samples");let mut push=redis::cmd("LPUSH");push.arg(&sample).arg(&formatted);commands.push(push);let mut trim=redis::cmd("LTRIM");trim.arg(&sample).arg(0).arg(255);commands.push(trim);let mut expire=redis::cmd("EXPIRE");expire.arg(&sample).arg(86400);commands.push(expire);for command in commands{if !matches!(checked(grant,tokio::time::timeout(Duration::from_millis(80),command.query_async::<redis::Value>(&mut cache))).await?,Ok(Ok(_))){return Ok(())}}Ok(())
 }
 async fn http(&self,raw:&str,timeout:u64,max_bytes:usize,grant:&dyn CurrentQuoteGrant)->Result<Option<String>>{
  let system_dns=crate::direct_preview::SystemDns;let dns:&dyn crate::direct_preview::PreviewDns=&system_dns;#[cfg(test)]let dns:&dyn crate::direct_preview::PreviewDns=self.http_fixture.as_ref().map(|f|f.dns.as_ref() as &dyn crate::direct_preview::PreviewDns).unwrap_or(dns);let initially_allowed=checked(grant,crate::direct_preview::eligible(raw,dns)).await??;if !initially_allowed{return Ok(None)}let mut current=crate::direct_preview::normalize(raw)?;
  let builder=reqwest::Client::builder().redirect(reqwest::redirect::Policy::none()).timeout(Duration::from_secs(timeout)).connect_timeout(Duration::from_secs(timeout.min(4))).user_agent("Mozilla/5.0 (compatible; mkultra.monster-link-preview/1.1; +https://mkultra.monster)");#[cfg(test)]let builder=if let Some(fixture)=&self.http_fixture{let mut builder=builder.no_proxy();for(host,address)in &fixture.addresses{builder=builder.resolve_to_addrs(host,&[*address]);}builder}else{builder};let client=builder.build()?;
  for hop in 0..=5{if current.is_empty()||!checked(grant,crate::direct_preview::eligible(&current,dns)).await??{return Ok(None)}let parsed=reqwest::Url::parse(&current)?;let host=parsed.host_str().unwrap_or("").to_ascii_lowercase();let provider=format!("preview:{host}");let now=chrono::Utc::now().timestamp();if !self.circuit_allow(&provider,now,grant).await?{return Ok(None)}
   let started=std::time::Instant::now();let response=checked(grant,client.get(&current).header("Accept","text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8").header("Accept-Language","en-US,en;q=0.8").send()).await?;let mut response=match response{Ok(r)=>r,Err(_)=>{self.timing(started.elapsed().as_secs_f64()*1000.0,grant).await?;self.circuit_result(&provider,true,chrono::Utc::now().timestamp(),grant).await?;return Ok(None)}};let code=response.status().as_u16();let location=response.headers().get(reqwest::header::LOCATION).and_then(|v|v.to_str().ok()).map(str::to_owned);let mut body=Vec::new();let mut ok=true;
   loop{match checked(grant,response.chunk()).await?{Ok(Some(chunk))=>{if body.len().saturating_add(chunk.len())>max_bytes{ok=false;break}body.extend_from_slice(&chunk)},Ok(None)=>break,Err(_)=>{ok=false;break}}}
   self.timing(started.elapsed().as_secs_f64()*1000.0,grant).await?;if !ok||code==429||code>=500{self.circuit_result(&provider,true,chrono::Utc::now().timestamp(),grant).await?}else if (200..500).contains(&code){self.circuit_result(&provider,false,chrono::Utc::now().timestamp(),grant).await?}
   if (300..400).contains(&code){if hop>=5{return Ok(None)}let Some(location)=location else{return Ok(None)};let Some(next)=resolve_redirect(&current,&location)else{return Ok(None)};if next==current||!checked(grant,crate::direct_preview::eligible(&next,dns)).await??{return Ok(None)}current=next;continue}
   if !ok||!(200..400).contains(&code)||body.is_empty(){return Ok(None)}return Ok(Some(String::from_utf8_lossy(&body).into_owned()))
  }Ok(None)
 }
