impl PreviewFetchTransport for ProcessPreviewTransport{
 fn http_get<'a>(&'a self,url:&'a str,timeout:u64,max_bytes:usize,grant:&'a dyn CurrentQuoteGrant)->Pin<Box<dyn Future<Output=Result<Option<String>>>+Send+'a>>{Box::pin(self.http(url,timeout,max_bytes,grant))}
 fn warm<'a>(&'a self,url:&'a str,grant:&'a dyn CurrentQuoteGrant)->Pin<Box<dyn Future<Output=Result<bool>>+Send+'a>>{Box::pin(async move{
  grant.require_current().await?;let url=crate::library::card::php_trim(url);if crate::profile_warm::actor_key(url).is_none(){return Ok(false)}let script=self.api_root.join("ap-link-preview-warm.php");if !script.is_file(){return Ok(false)}let Ok(lock)=std::fs::OpenOptions::new().read(true).write(true).create(true).truncate(false).open(self.temp_root.join(format!("vaak-lp-{}.lock",hash(url))))else{return Ok(false)};if lock.try_lock().is_err(){return Ok(false)}
  let count=checked(grant,tokio::time::timeout(Duration::from_millis(250),tokio::process::Command::new("pgrep").args(["-fc","ap-link-preview-warm\\.php"]).kill_on_drop(true).output())).await?;if let Ok(Ok(output))=count{if process_capped(&String::from_utf8_lossy(&output.stdout)){return Ok(false)}}drop(lock);
  grant.require_current().await?;let spawn=tokio::process::Command::new("nohup").arg(&self.php).arg(script).arg(url).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).spawn();let started=match spawn{Ok(mut child)=>{tokio::spawn(async move{let _=child.wait().await;});true},Err(_)=>false};grant.require_current().await?;Ok(started)
 })}
}
fn process_capped(raw:&str)->bool{let count=crate::library::card::php_trim(raw);if count.is_empty()||!count.bytes().all(|b|b.is_ascii_digit()){return false}let n=count.trim_start_matches('0');n.len()>1||n.as_bytes().first().is_some_and(|b|*b>=b'3')}
/// PHP preserves relative dot segments rather than URL::join normalization.
pub(crate) fn resolve_redirect(from:&str,location:&str)->Option<String>{let location=crate::library::card::php_trim(location);if location.is_empty(){return None}let pattern=regex::Regex::new(r"(?i)^(https?)://(?:[^/?#]*@)?([^:/?#]+)(?::([0-9]+))?([^?#]*)(?:[?#].*)?$").unwrap();let next=if location.starts_with("https://")||location.starts_with("http://"){location.into()}else{let c=pattern.captures(from)?;if location.starts_with("//"){format!("{}:{location}",&c[1])}else{let origin=format!("{}://{}{}",&c[1],&c[2],c.get(3).map(|p|format!(":{}",p.as_str())).unwrap_or_default());if location.starts_with('/') {format!("{origin}{location}")}else{let path=c.get(4).map(|p|p.as_str()).filter(|p|!p.is_empty()).unwrap_or("/");let dir=regex::Regex::new(r"/[^/]*$").unwrap().replace(path,"/");format!("{origin}{dir}{location}")}}};crate::direct_preview::normalize(&next).ok().filter(|s|!s.is_empty())}
